arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) printf '%s' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
cd /tmp/friends-monica-conv && GIT_ASKPASS=/tmp/git-askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/monica 2>&1 | sed -E 's#//[^@]*@#//***@#g' | tail -5
